sys_script_include.script:
var IllumioAddToECCQueue = Class.create();
IllumioAddToECCQueue.prototype = {
    initialize: function(probe, midserver, parameters) {
        this.probe = probe; // probe name
        this.midServer = midserver; // mid server name
        this.parameters = parameters; // extra parameters to be passed
        this.utils = new IllumioUtils();
        // Two names for the same thing, both in use: authentication, discovery, async polling and
        // preview send `illumio_scheduled_job_id`; sync and deletion send `jobSysId`. Reading only
        // the first left this undefined for sync and deletion -- which meant the isJobCancelled
        // guard below was a no-op on exactly the two highest-volume paths, and the log lines from
        // this class had no job to correlate to. Both names are read rather than renamed because
        // the MID reads them by name on the other side.
        this.illumioJobSysId = this.parameters["illumio_scheduled_job_id"] ||
            this.parameters["jobSysId"];
        this.logger = new IllumioLogger(this.illumioJobSysId, 'IllumioAddToECCQueue');
    },

    /**
     * Insert to ECC queue
     * @returns {boolean} true if the insert is successful else false
     */
    insert: function() {

        try {
            var ecc = new GlideRecord("ecc_queue");
            ecc.initialize();
            ecc.agent = 'mid.server.' + this.midServer;
            ecc.topic = 'JavascriptProbe';
            ecc.queue = 'output';
            ecc.state = 'ready';
            ecc.name = this.probe;

            var xmlstring = '<?xml version="1.0" encoding="UTF-8"?><parameters></parameters>';
            var xmldoc = new XMLDocument2();
            xmldoc.parseXML(xmlstring);

            // add skip sensors
            var el = xmldoc.createElement("parameter");
            el.setAttribute("name", "skip_sensor");
            el.setAttribute("value", "true");

            // add probe name to be execute
            el = xmldoc.createElement("parameter");
            el.setAttribute("name", "probe_name");
            el.setAttribute("value", this.probe + 'Run');

            // add given parameters
            for (var param in this.parameters) {
                el = xmldoc.createElement("parameter");
                el.setAttribute("name", "glide.jms." + param);
                el.setAttribute("value", this.parameters[param]);
            }

            ecc.payload = xmldoc + "";

            if (this.utils.isJobCancelled(this.illumioJobSysId)) {
                return false;
            }

            // W6: the handoff boundary. Everything past this line runs on the MID, where nothing
            // this application logs reaches the instance except through the W5 push. Saying what
            // was queued, to which MID, for which job is what lets a missing "Probe entered."
            // line on the other side mean something -- without this, both halves look silent and
            // there is no way to tell which one never ran.
            this.logger.info('HANDOFF: queueing probe ' + this.probe + ' for MID Server ' +
                this.midServer + '.');

            // add it to the ECC queue
            var eccSysId = ecc.insert();

            // The return used to be ignored and this method reported success unconditionally. An
            // insert that is refused rather than thrown -- an ACL, a bad agent value -- then left
            // the caller believing the MID had work it was never given, and the job sat in
            // `running` until the 30-minute wall-clock cap force-cancelled it. Reporting the
            // failure lets the caller fail the job now, with a reason.
            if (gs.nil(eccSysId)) {
                this.logger.error('HANDOFF FAILED: the ECC queue insert for probe ' + this.probe +
                    ' returned no sys_id. Nothing was sent to MID Server ' + this.midServer + '.');
                return false;
            }

            return true;
        } catch (exception) {
            this.logger.error('Exception occurred while adding to ECC queue. Exception: ' + exception);
            return false;
        }
    },

    type: 'IllumioAddToECCQueue'
};
